async fn agent_texture_budget_rejects_whole_upload_and_stores_nothing() {
    let store = ResourceStore::new(ResourceStoreConfig::default());
    // 8x8 RGBA = 256 bytes; the agent has 100 bytes of headroom.
    let tight = AgentBudget {
        texture_bytes_total_limit: 1000,
        texture_bytes_total_used: 900,
    };

    let err = upload(&store, "a", 1, 8, 1, tight.clone())
        .await
        .unwrap_err();

    assert!(matches!(err, ResourceError::BudgetExceeded { .. }));
    assert!(
        !stored(&store, 8, 1),
        "rejected upload must leave no resource behind"
    );
    assert_eq!(store.dedup_index().total_decoded_bytes(), 0);

    // The cap is a cap, not a penalty: a fitting upload straight after succeeds.
    upload(&store, "a", 2, 2, 2, tight).await.unwrap(); // 16 bytes
    assert!(stored(&store, 2, 2));
}

fn aggregate_limits_are_atomic_across_agents() {
    let enforcer = RuntimeMutationBudgetEnforcer::with_limits(2, 2, 100);
    let agent_a = SceneId::new();
    let agent_b = SceneId::new();
    for (session_id, name) in [(agent_a, "agent-a"), (agent_b, "agent-b")] {
        assert_eq!(
            enforcer.register_session(
                session_id,
                name.to_string(),
                ResourceBudget {
                    max_tiles: 8,
                    max_texture_bytes: 100,
                    ..ResourceBudget::default()
                },
                true,
                MutationBudgetUsage::default(),
            ),
            MutationBudgetDecision::Allow
        );
    }
    assert!(matches!(
        enforcer.register_session(
            SceneId::new(),
            "agent-c".to_string(),
            ResourceBudget::default(),
            true,
            MutationBudgetUsage::default(),
        ),
        MutationBudgetDecision::Reject { message, .. } if message.contains("resident_sessions")
    ));

    assert_eq!(
        enforcer.reserve_mutation(agent_a, 1, 60, 1),
        MutationBudgetDecision::Allow
    );
    assert!(matches!(
        enforcer.reserve_mutation(agent_b, 2, 0, 1),
        MutationBudgetDecision::Reject { message, .. } if message.contains("leased_tiles")
    ));
    assert!(matches!(
        enforcer.reserve_mutation(agent_b, 1, 50, 1),
        MutationBudgetDecision::Reject { message, .. } if message.contains("agent_leased_texture_bytes")
    ));
    assert_eq!(
        enforcer.reserve_mutation(agent_b, 1, 40, 1),
        MutationBudgetDecision::Allow
    );
}

async fn chunk_protocol_errors_have_stable_codes() {
    let store = ResourceStore::new(ResourceStoreConfig::default());
    let data = rgba(2, 1);
    let id = UploadId::from_bytes([1; 16]);
    store
        .handle_upload_start(chunked_start("a", 1, 2, &data))
        .await
        .unwrap();

    let out_of_order = store
        .handle_upload_chunk("a", id, 1, data.clone())
        .await
        .unwrap_err();
    let unknown = store
        .handle_upload_chunk("a", UploadId::from_bytes([9; 16]), 0, data.clone())
        .await
        .unwrap_err();
    let oversized = store
        .handle_upload_chunk("a", id, 0, vec![0; CHUNK_SIZE_LIMIT + 1])
        .await
        .unwrap_err();
    let too_many = {
        for n in 2..=MAX_CONCURRENT_UPLOADS_PER_AGENT as u8 {
            store
                .handle_upload_start(chunked_start("a", n, 2, &data))
                .await
                .unwrap();
        }
        store
            .handle_upload_start(chunked_start("a", 50, 2, &data))
            .await
            .unwrap_err()
    };

    for err in [&out_of_order, &unknown, &oversized] {
        assert_eq!(err.wire_code(), "RESOURCE_INVALID_CHUNK");
    }
    // The out-of-order message tells the sender which index to send.
    assert!(out_of_order.to_string().contains("expected chunk index 0"));
    assert_eq!(too_many.wire_code(), "RESOURCE_TOO_MANY_UPLOADS");
}

async fn chunked_upload_rejected_at_complete_frees_its_slot_and_stores_nothing() {
    let store = ResourceStore::new(ResourceStoreConfig::default());
    let data = rgba(8, 1);
    let tight = AgentBudget {
        texture_bytes_total_limit: 100,
        texture_bytes_total_used: 0,
    };
    let id = UploadId::from_bytes([1; 16]);
    store
        .handle_upload_start(chunked_start("a", 1, 8, &data))
        .await
        .unwrap();
    store
        .handle_upload_chunk("a", id, 0, data.clone())
        .await
        .unwrap();

    let err = store
        .handle_upload_complete("a", id, &caps(), &tight)
        .await
        .unwrap_err();

    assert!(matches!(err, ResourceError::BudgetExceeded { .. }));
    assert_eq!(store.in_flight_count("a").await, 0);
    assert!(!stored(&store, 8, 1));
}

async fn delay_ms_holds_content_until_due() {
    let (server, clock) = server();
    let v = call(
        &server,
        "hud_publish",
        json!({"surface": "zone:subtitle", "content": "later", "delay_ms": 5000, "ttl_ms": 1000}),
    )
    .await;
    assert_eq!(v["expires_in_ms"], 6000);
    let mut scene = server.scene.lock().await;
    scene.apply_due_batches();
    assert!(
        scene
            .zone_registry
            .active_publishes
            .get("subtitle")
            .is_none_or(Vec::is_empty),
        "not shown before present_at"
    );
    clock.advance(5_000);
    scene.apply_due_batches();
    let rec = &scene.zone_registry.active_publishes["subtitle"][0];
    assert_eq!(
        rec.expires_at_wall_us,
        Some(7_000_000),
        "expiry counts from presentation"
    );
}

fn disconnect_then_reconnect_within_grace_resumes_same_surface_without_duplication() {
    const FIRST: &str = "ALPHA-committed-before-drop";
    const SECOND: &str = "BETA-continued-after-resume";
    let (mut driver, mut scene, tab, mut processor, clock) = clocked();
    publish(&mut driver, "p", FIRST, clock.now_us());
    driver.drain(&mut scene, &mut processor, Some(tab));
    let (tile_id, lease_id) = (tile(&driver, "p"), lease(&driver, "p"));

    driver.mark_all_projections_disconnected();
    clock.advance(100);
    driver.drain(&mut scene, &mut processor, Some(tab));
    assert!(
        scene.lease_is_orphaned(&lease_id),
        "badge shown, grace running"
    );
    assert!(driver.degraded(&key("p")));

    clock.advance(5_000);
    publish(&mut driver, "p", SECOND, clock.now_us());
    driver.drain(&mut scene, &mut processor, Some(tab));
    assert_eq!(
        tile(&driver, "p"),
        tile_id,
        "resume reuses the original surface"
    );
    assert_eq!(scene.tile_count(), 1);
    assert!(scene.lease_is_active(&lease_id));
    assert!(!driver.degraded(&key("p")));
    let content = tile_markdown(&scene, tile_id);
    assert_eq!(content.matches(FIRST).count(), 1, "{content}");
    assert_eq!(content.matches(SECOND).count(), 1, "{content}");
}

fn disconnect_transitions_to_orphaned_and_sets_disconnection_badge() {
    let (mut scene, clock) = make_scene(0);
    let tab_id = setup_active_tab(&mut scene);

    // Grant lease and create tile.
    let lease_id = grant_lease(&mut scene, "dashboard-agent");
    let tile_id = create_tile(&mut scene, tab_id, "dashboard-agent", lease_id);

    // Verify initial state: ACTIVE, no badge.
    assert_eq!(
        scene.leases[&lease_id].state,
        LeaseState::Active,
        "lease must start as ACTIVE"
    );
    assert_eq!(
        scene.tiles[&tile_id].visual_hint,
        TileVisualHint::None,
        "tile must have no visual hint initially"
    );

    // Simulate agent disconnect at t=5_000ms (5 seconds after activation).
    clock.advance(5_000);
    let now_ms = clock.now_millis();
    scene
        .disconnect_lease(&lease_id, now_ms)
        .expect("disconnect must succeed from ACTIVE state");

    // Lease transitions to ORPHANED.
    assert_eq!(
        scene.leases[&lease_id].state,
        LeaseState::Orphaned,
        "lease must transition to ORPHANED on disconnect"
    );

    // Tile receives DisconnectionBadge (within 1 frame = synchronous in the scene graph).
    assert_eq!(
        scene.tiles[&tile_id].visual_hint,
        TileVisualHint::DisconnectionBadge,
        "tile must have DisconnectionBadge after disconnect"
    );

    // Tile still exists (frozen at last state — not removed during grace period).
    assert!(
        scene.tiles.contains_key(&tile_id),
        "tile must still exist during orphan grace period"
    );
}

fn error_codes_are_unique_and_documented() {
    let mut seen = std::collections::HashSet::new();
    for code in ERROR_CODES {
        assert!(seen.insert(code), "duplicate {code}");
    }
    let api = include_str!("../../../docs/api.md");
    for code in ERROR_CODES {
        assert!(
            api.contains(&format!("`{code}`")),
            "{code} missing from docs/api.md"
        );
    }
}

async fn every_returned_code_is_in_the_closed_set() {
    let (server, _) = server();
    let cases = [
        (
            "hud_publish",
            json!({"surface": "zone:nope", "content": "x"}),
        ),
        (
            "hud_publish",
            json!({"surface": "widget:nope", "params": {}}),
        ),
        (
            "hud_publish",
            json!({"surface": "widget:gauge", "params": {"level": "high"}}),
        ),
        (
            "hud_publish",
            json!({"surface": "portal:p", "content": "x"}),
        ),
        ("hud_hold", json!({"surface": "zone:subtitle", "ttl_ms": 1})),
        ("hud_clear", json!({"surface": "portal:p"})),
        ("hud_input", json!({"bogus": 1})),
    ];
    for (tool, args) in cases {
        let err = call_err(&server, tool, args.clone()).await;
        let code = err["code"].as_str().unwrap();
        assert!(
            crate::error::ERROR_CODES.contains(&code),
            "{tool} {args}: {code}"
        );
    }
}

fn grace_period_expiry_removes_tile_and_nodes() {
    let (mut scene, clock) = make_scene(0);
    let tab_id = setup_active_tab(&mut scene);

    let lease_id = grant_lease(&mut scene, "dashboard-agent");
    let tile_id = create_tile(&mut scene, tab_id, "dashboard-agent", lease_id);

    // Verify tile exists.
    assert!(scene.tiles.contains_key(&tile_id));

    // Disconnect at t=1_000ms.
    clock.advance(1_000);
    let disconnect_ms = clock.now_millis();
    scene.disconnect_lease(&lease_id, disconnect_ms).unwrap();

    // Advance past 30-second grace period (31_000ms after disconnect).
    // Total time: 1_000 + 31_000 = 32_000ms — still within 60s TTL.
    clock.advance(31_000);

    // expire_leases sweeps grace-expired orphaned leases.
    let expiries = scene.expire_leases();

    // At least one expiry must have occurred for this lease.
    assert!(
        expiries.iter().any(|e| e.lease_id == lease_id),
        "expire_leases must return an expiry for the grace-expired orphaned lease"
    );

    // Lease state must be EXPIRED or REVOKED (terminal).
    // The lease entry remains in the map after expiry until GC; use expect() to
    // make a missing entry detectable rather than silently passing.
    let lease = scene
        .leases
        .get(&lease_id)
        .expect("lease must still be present in the map after grace expiry");
    assert!(
        lease.state == LeaseState::Expired || lease.state == LeaseState::Revoked,
        "lease must be in a terminal state after grace expiry, got {:?}",
        lease.state
    );

    // Tile must have been removed from the scene graph.
    assert!(
        !scene.tiles.contains_key(&tile_id),
        "tile must be removed from scene graph after grace period expiry"
    );
}

async fn grpc_batch_expires_at_sweeps_tile() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, (lease_id, tile_id_bytes), _client) =
        tile_agent(clock.clone()).await;
    let tile_id = bytes_to_scene_id(&tile_id_bytes).unwrap();
    let expires_at = clock.now_us() + 8_000_000;
    let timing = Some(TimingHints {
        present_at_wall_us: 0,
        expires_at_wall_us: expires_at,
    });
    match send_batch(
        &tx,
        &mut stream,
        3,
        &lease_id,
        vec![set_root_proto(&tile_id_bytes)],
        timing,
    )
    .await
    .payload
    {
        Some(ServerPayload::RequestResult(r)) => assert!(r.ok, "{r:?}"),
        other => panic!("expected RequestResult, got {other:?}"),
    }

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    assert_eq!(scene.tiles[&tile_id].expires_at, Some(expires_at));
    assert_eq!(scene.next_timed_content_wall_us(), Some(expires_at));
    clock.advance(7_999);
    assert!(scene.drain_expired_tiles().is_empty());
    clock.advance(2);
    assert_eq!(scene.drain_expired_tiles(), vec![tile_id]);
    assert_eq!(scene.tile_count(), 0);
    drop(scene);
    drop(st);
    server.abort();
}

async fn grpc_batch_present_at_holds_content_until_due() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, (lease_id, tile_id_bytes), _client) =
        tile_agent(clock.clone()).await;
    let tile_id = bytes_to_scene_id(&tile_id_bytes).unwrap();

    let present_at = clock.now_us() + 5_000_000;
    let timing = Some(TimingHints {
        present_at_wall_us: present_at,
        expires_at_wall_us: 0,
    });
    match send_batch(
        &tx,
        &mut stream,
        4,
        &lease_id,
        vec![set_root_proto(&tile_id_bytes)],
        timing,
    )
    .await
    .payload
    {
        Some(ServerPayload::RequestResult(r)) => assert!(r.ok, "{r:?}"),
        other => panic!("expected MutationResult, got {other:?}"),
    }

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    assert!(scene.tiles[&tile_id].root_node.is_none(), "not shown early");
    clock.advance(4_999);
    assert!(scene.apply_due_batches().is_empty());
    assert!(scene.tiles[&tile_id].root_node.is_none());
    clock.advance(1);
    let applied = scene.apply_due_batches();
    assert!(applied[0].applied, "{:?}", applied[0].error);
    assert!(scene.tiles[&tile_id].root_node.is_some(), "shown when due");
    drop(scene);
    drop(st);
    server.abort();
}

async fn grpc_disconnect_orphans_leases_and_badges_tiles() {
    let (mut client, server, state, _exp) =
        setup_test_with_lease_expiry_clock(wall_aligned_clock()).await;
    let session = connect_hold_tile(&mut client, "orphan-agent").await;
    let peer = connect_hold_tile(&mut client, "orphan-agent").await;
    assert_ne!(session.session_id, peer.session_id);
    let (duplicate_cleanup, mut peer_cleanup) = {
        let mut st = state.lock().await;
        (
            st.sessions.observe_cleanup(&session.session_id),
            st.sessions.observe_cleanup(&peer.session_id),
        )
    };
    let (_token, lease_id, tile_id) = session.disconnect(&state).await;
    // A second observer starts awaiting after cleanup already completed.
    await_session_cleanup(duplicate_cleanup).await;

    let st = state.lock().await;
    let scene = st.scene.lock().await;
    assert_eq!(scene.leases[&lease_id].state, LeaseState::Orphaned);
    let tile = scene.tiles.get(&tile_id).expect("orphaned content is kept");
    assert_eq!(
        tile.visual_hint,
        tze_hud_scene::lease::TileVisualHint::DisconnectionBadge
    );
    assert_eq!(
        st.sessions.session_count(),
        1,
        "only the peer remains connected"
    );
    assert_eq!(scene.leases[&peer.lease_id].state, LeaseState::Active);
    assert_eq!(
        scene.tiles[&peer.tile_id].visual_hint,
        tze_hud_scene::lease::TileVisualHint::None
    );
    assert_eq!(
        peer_cleanup.try_recv(),
        Err(tokio::sync::oneshot::error::TryRecvError::Empty)
    );
    drop(scene);
    drop(st);
    peer.disconnect(&state).await;
    await_session_cleanup(peer_cleanup).await;
    assert_eq!(state.lock().await.sessions.session_count(), 0);
    server.abort();
}

async fn grpc_grace_expiry_reclaims_orphaned_lease_and_rejects_resume() {
    let clock = wall_aligned_clock();
    let (mut client, server, state, _exp) = setup_test_with_lease_expiry_clock(clock.clone()).await;
    let (token, lease_id, tile_id) =
        connect_hold_tile_and_disconnect(&mut client, &state, "late-agent").await;

    {
        let st = state.lock().await;
        let mut scene = st.scene.lock().await;
        assert_eq!(st.sessions.session_count(), 0);
        assert_eq!(scene.leases[&lease_id].state, LeaseState::Orphaned);
        clock.advance(crate::token::DEFAULT_GRACE_PERIOD_MS + 1);
        // The compositor's per-frame sweep, as in production.
        let expiries = scene.expire_leases();
        assert_eq!(expiries.len(), 1);
        assert_eq!(expiries[0].lease_id, lease_id);
        assert_eq!(expiries[0].removed_tiles, vec![tile_id]);
        assert_eq!(scene.tile_count(), 0);
    }

    let (_tx, mut stream) = send_resume(&mut client, "late-agent", token).await;
    match stream.next().await.unwrap().unwrap().payload {
        Some(ServerPayload::SessionError(e)) => assert_eq!(e.code, "SESSION_GRACE_EXPIRED"),
        other => panic!("expected SESSION_GRACE_EXPIRED, got {other:?}"),
    }
    server.abort();
}

async fn grpc_resume_within_grace_restores_same_lease_and_tile() {
    let clock = wall_aligned_clock();
    let (mut client, server, state, _exp) = setup_test_with_lease_expiry_clock(clock.clone()).await;
    let (token, lease_id, tile_id) =
        connect_hold_tile_and_disconnect(&mut client, &state, "resume-agent").await;

    clock.advance(crate::token::DEFAULT_GRACE_PERIOD_MS - 1);
    let (_tx, mut stream) = send_resume(&mut client, "resume-agent", token).await;
    match stream.next().await.unwrap().unwrap().payload {
        Some(ServerPayload::SessionResumeResult(r)) => assert!(r.accepted),
        other => panic!("expected SessionResumeResult, got {other:?}"),
    }

    let st = state.lock().await;
    let scene = st.scene.lock().await;
    assert_eq!(scene.leases[&lease_id].state, LeaseState::Active);
    assert_eq!(scene.tile_count(), 1, "resume must not duplicate surfaces");
    assert_eq!(
        scene.tiles[&tile_id].visual_hint,
        tze_hud_scene::lease::TileVisualHint::None
    );
    drop(scene);
    drop(st);
    server.abort();
}

async fn grpc_zone_publish_expires_at_is_swept() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, _client) = zone_publisher(clock.clone()).await;
    let expires_at = clock.now_us() + 3_000_000;

    let ack = publish_and_ack(
        &tx,
        &mut stream,
        2,
        subtitle_publish("until", 0, 0, expires_at),
    )
    .await;
    assert!(ack.ok, "{ack:?}");

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    assert_eq!(
        scene.zone_registry.active_publishes["subtitle"][0].expires_at_wall_us,
        Some(expires_at)
    );
    clock.advance(3_001);
    scene.drain_expired_zone_publications();
    assert!(subtitle_texts(&scene).is_empty());
    drop(scene);
    drop(st);
    server.abort();
}

async fn grpc_zone_publish_present_at_is_held_until_due() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, _client) = zone_publisher(clock.clone()).await;
    let present_at = clock.now_us() + 5_000_000;

    let ack = publish_and_ack(
        &tx,
        &mut stream,
        2,
        subtitle_publish("later", 2_000, present_at, 0),
    )
    .await;
    assert!(ack.ok, "{ack:?}");

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    assert!(subtitle_texts(&scene).is_empty(), "not shown early");
    assert_eq!(scene.next_timed_content_wall_us(), Some(present_at));
    clock.advance(4_999);
    assert!(scene.apply_due_batches().is_empty());
    assert!(subtitle_texts(&scene).is_empty(), "still not due");
    clock.advance(1);
    let applied = scene.apply_due_batches();
    assert_eq!(applied.len(), 1);
    assert!(applied[0].applied);
    assert_eq!(subtitle_texts(&scene), vec!["later".to_string()]);
    assert_eq!(
        scene.zone_registry.active_publishes["subtitle"][0].expires_at_wall_us,
        Some(present_at + 2_000_000)
    );
    drop(scene);
    drop(st);
    server.abort();
}

async fn grpc_zone_publish_ttl_sets_expiry_and_is_swept() {
    let clock = wall_aligned_clock();
    let (tx, mut stream, state, server, _client) = zone_publisher(clock.clone()).await;

    let ack = publish_and_ack(&tx, &mut stream, 2, subtitle_publish("brief", 8_000, 0, 0)).await;
    assert!(ack.ok, "{ack:?}");

    let st = state.lock().await;
    let mut scene = st.scene.lock().await;
    let now_us = scene.now_wall_us();
    let record = &scene.zone_registry.active_publishes["subtitle"][0];
    assert_eq!(record.expires_at_wall_us, Some(now_us + 8_000_000));
    clock.advance(7_999);
    scene.drain_expired_zone_publications();
    assert_eq!(subtitle_texts(&scene), vec!["brief".to_string()]);
    clock.advance(2);
    scene.drain_expired_zone_publications();
    assert!(
        subtitle_texts(&scene).is_empty(),
        "expired content is swept"
    );
    drop(scene);
    drop(st);
    server.abort();
}

async fn hold_moves_the_fade_deadline_and_ttl_zero_never_fades() {
    use std::sync::Arc;
    use std::time::Duration;
    use tze_hud_scene::clock::TestClock;

    let (mut compositor, _surface) = require_gpu!(make_compositor_and_surface(320, 200).await);
    let clock = Arc::new(TestClock::new(1_000));
    let mut scene =
        countdown_notification_scene_on(SceneGraph::new_with_clock(1280.0, 720.0, clock.clone()));
    let delay = |c: &Compositor| {
        let states: Vec<_> = c.pub_animation_states["notification-area"]
            .values()
            .collect();
        assert_eq!(states.len(), 1);
        states[0].ttl_ms
    };
    compositor.update_publication_animations(&scene);
    assert_eq!(
        delay(&compositor),
        Some(7_850),
        "urgency default, 8 s - fade"
    );

    // 5 s in, hold 20 s: the fade is due 19.85 s from now, one deadline.
    clock.advance(5_000);
    let first_deadline = compositor.next_animation_deadline().unwrap();
    assert!(scene.hold_zone_publications("notification-area", "agent-a", Some(20_000_000)));
    compositor.update_publication_animations(&scene);
    assert_eq!(delay(&compositor), Some(19_850));
    let moved = compositor.next_animation_deadline().unwrap();
    assert!(
        moved > first_deadline + Duration::from_secs(10),
        "deadline moved out"
    );
    assert!(
        !compositor.has_inflight_animation(&scene),
        "still just counting down"
    );

    // ttl_ms:0 holds: no deadline, no animation, past auto_clear_ms and the sweep.
    assert!(scene.hold_zone_publications("notification-area", "agent-a", None));
    compositor.update_publication_animations(&scene);
    assert_eq!(delay(&compositor), None);
    assert_eq!(
        compositor.next_animation_deadline(),
        None,
        "held schedules no wake"
    );
    clock.advance(60_000);
    assert_eq!(
        scene.drain_expired_zone_publications(),
        0,
        "scene sweep keeps it"
    );
    compositor.update_publication_animations(&scene);
    assert!(!compositor.has_inflight_animation(&scene));
    assert_eq!(
        compositor.pub_opacity(
            "notification-area",
            &scene.zone_registry.active_publishes["notification-area"][0]
        ),
        1.0
    );

    // hud_clear removes it.
    scene
        .clear_zone_for_publisher("notification-area", "agent-a")
        .unwrap();
    compositor.update_publication_animations(&scene);
    assert!(
        compositor
            .pub_animation_states
            .values()
            .all(|zone| zone.is_empty())
    );
    assert_eq!(compositor.next_animation_deadline(), None);
}

async fn hotkey_event_enters_safe_mode_and_suspends_leases() {
    let state = WindowedRuntimeState::new_headless();
    let lease_id = state
        .shared_state
        .lock()
        .await
        .scene
        .lock()
        .await
        .grant_lease("agent", 60_000);
    let tx = spawn_safe_mode_toggle_bridge(
        &tokio::runtime::Handle::current(),
        Arc::clone(&state.shared_state),
        Arc::clone(&state.chrome_state),
        state.wake.render_notifier(),
        state.shutdown.clone(),
    );

    let lease_state = || async {
        let st = state.shared_state.lock().await;
        let scene = st.scene.lock().await;
        scene.leases[&lease_id].state
    };
    let atomic = Arc::clone(&state.safe_mode_atomic);
    let wait_for_active = |want: bool| {
        let atomic = Arc::clone(&atomic);
        async move {
            for _ in 0..200 {
                if atomic.load(Ordering::Acquire) == want {
                    return;
                }
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
            panic!("safe mode never became {want}");
        }
    };

    tx.send(()).unwrap();
    wait_for_active(true).await;
    assert_eq!(lease_state().await, LeaseState::Suspended);
    assert!(state.chrome_state.read().unwrap().safe_mode_active);

    tx.send(()).unwrap();
    wait_for_active(false).await;
    assert_eq!(lease_state().await, LeaseState::Active);
    assert!(!state.chrome_state.read().unwrap().safe_mode_active);
}

async fn hud_publish_in_safe_mode_returns_safe_mode_active() {
    let (server, _) = server();
    let (server, hub) = hub_portal(server);
    // Held before safe mode, so hud_hold has something to extend.
    for surface in ["zone:subtitle", "widget:gauge"] {
        let args = match surface {
            "widget:gauge" => json!({"surface": surface, "params": {"level": 0.5}}),
            _ => json!({"surface": surface, "content": "a"}),
        };
        call(&server, "hud_publish", args).await;
    }
    call(
        &server,
        "hud_publish",
        json!({"surface": "portal:main", "content": "before"}),
    )
    .await;
    server
        .scene
        .lock()
        .await
        .push_pending_action(PendingAction {
            publisher_namespace: AgentDirectory::unrestricted(psk())
                .resolve(&psk(), "")
                .unwrap()
                .agent_id,
            zone_name: "notification-area".into(),
            callback_id: "approve".into(),
        });

    set_safe_mode(&server, true);
    for surface in ["zone:subtitle", "widget:gauge", "portal:main"] {
        let publish = match surface {
            "widget:gauge" => json!({"surface": surface, "params": {"level": 0.9}}),
            _ => json!({"surface": surface, "content": "during"}),
        };
        let err = call_err(&server, "hud_publish", publish).await;
        assert_eq!(err["code"], "SAFE_MODE_ACTIVE", "publish {surface}");
        let err = call_err(
            &server,
            "hud_hold",
            json!({"surface": surface, "ttl_ms": 1000}),
        )
        .await;
        assert_eq!(err["code"], "SAFE_MODE_ACTIVE", "hold {surface}");
    }
    let key = PortalKey::new(psk_agent(), "main");
    assert_eq!(
        hub.lock().unwrap().get(&key).unwrap().transcript.len(),
        1,
        "nothing reached the portal driver during safe mode"
    );

    // Reading stays open: already-queued input is still delivered.
    let v = call(&server, "hud_input", json!({})).await;
    assert_eq!(v["items"][0]["action"], "approve");
}

fn mutation_batch_oversized_rejected_with_structured_error() {
    let mut scene = clean_scene();
    let tab = scene.create_tab("Tab", 0).unwrap();
    let lease = scene.grant_lease("agent", 300_000);

    let mutations: Vec<SceneMutation> = (0..=MAX_BATCH_SIZE)
        .map(|z| SceneMutation::CreateTile {
            tab_id: tab,
            namespace: "agent".into(),
            lease_id: lease,
            bounds: Rect::new(0.0, 0.0, 10.0, 10.0),
            z_order: z as u32,
        })
        .collect();

    let batch = make_batch("agent", Some(lease), mutations);
    let result = scene.apply_batch(&batch);

    assert!(!result.applied, "oversized batch must be rejected");
