async fn notification_ttl_zero_is_held_and_hold_retimes_it() {
    let (server, clock) = server();
    let notif = json!({"surface": "zone:notification-area",
        "content": {"title": "t", "body": "b"}});
    let mut held = notif.clone();
    held["ttl_ms"] = json!(0);
    let v = call(&server, "hud_publish", held).await;
    assert_eq!(v, json!({"ok": true}));
    {
        let mut scene = server.scene.lock().await;
        let rec = &scene.zone_registry.active_publishes["notification-area"][0];
        assert_eq!(rec.expires_at_wall_us, None, "no urgency-derived expiry");
        clock.advance(120_000);
        assert_eq!(scene.drain_expired_zone_publications(), 0);
    }
    // Hold with a ttl counts from now; hold 0 releases it again.
    let v = call(
        &server,
        "hud_hold",
        json!({"surface": "zone:notification-area", "ttl_ms": 5000}),
    )
    .await;
    assert_eq!(v, json!({"ok": true, "expires_in_ms": 5000}));
    {
        let scene = server.scene.lock().await;
        assert_eq!(
            scene.zone_registry.active_publishes["notification-area"][0].expires_at_wall_us,
            Some(scene.now_wall_us() + 5_000_000)
        );
    }
    // A shorter hold replaces the expiry (it is not the later of old and new).
    call(
        &server,
        "hud_hold",
        json!({"surface": "zone:notification-area", "ttl_ms": 1000}),
    )
    .await;
    {
        let scene = server.scene.lock().await;
        assert_eq!(
            scene.zone_registry.active_publishes["notification-area"][0].expires_at_wall_us,
            Some(scene.now_wall_us() + 1_000_000)
        );
    }
    call(
        &server,
        "hud_hold",
        json!({"surface": "zone:notification-area", "ttl_ms": 0}),
    )
    .await;
    {
        let mut scene = server.scene.lock().await;
        clock.advance(120_000);
        assert_eq!(scene.drain_expired_zone_publications(), 0);
    }
    call(
        &server,
        "hud_clear",
        json!({"surface": "zone:notification-area"}),
    )
    .await;
    let scene = server.scene.lock().await;
    assert!(
        scene
            .zone_registry
            .active_publishes
            .get("notification-area")
            .is_none_or(Vec::is_empty)
    );
}

async fn orphaned_tile_emits_disconnection_badge_draw_cmd() {
    let (mut compositor, _surface) = require_gpu!(make_compositor_and_surface(400, 300).await);
    compositor.overlay_mode = true;

    let mut scene = SceneGraph::new(400.0, 300.0);
    let tab_id = scene.create_tab("agent", 0).unwrap();
    let lease_id = scene.grant_lease("agent", 60_000);
    scene
        .create_tile(
            tab_id,
            "agent",
            lease_id,
            Rect::new(50.0, 40.0, 300.0, 200.0),
            1,
        )
        .unwrap();

    let badge_verts = |compositor: &Compositor, scene: &SceneGraph| {
        let mut verts: Vec<crate::pipeline::RectVertex> = Vec::new();
        compositor.append_disconnect_badge_vertices(scene, &mut verts, 400.0, 300.0);
        verts
    };

    assert!(
        badge_verts(&compositor, &scene).is_empty(),
        "a live tile must not show the disconnection badge"
    );

    scene.disconnect_lease(&lease_id, 1_000).unwrap();
    let verts = badge_verts(&compositor, &scene);
    assert_eq!(verts.len(), 6, "orphaned tile must emit one badge quad");
    let tokens =
        crate::renderer::token_colors::resolve_disconnect_badge_tokens(&compositor.token_map);
    let expected = compositor.gpu_color_raw(tokens.color);
    assert!(expected[3] > 0.0, "badge default alpha must be visible");
    for v in &verts {
        assert!(
            v.color
                .iter()
                .zip(expected.iter())
                .all(|(a, b)| (a - b).abs() < 1e-3),
            "badge must carry the token-driven color"
        );
    }

    scene.reconnect_lease(&lease_id, 2_000).unwrap();
    assert!(
        badge_verts(&compositor, &scene).is_empty(),
        "resuming within grace must clear the badge"
    );
}

