    assert!(lease.suspended_at_ms.is_some());
    assert!(lease.ttl_remaining_at_suspend_ms.is_some());
    // 60_000 - 10_000 = 50_000 remaining at suspend
    assert_eq!(lease.ttl_remaining_at_suspend_ms, Some(50_000));
}

