async fn upload_slot_cap_is_per_agent_and_freed_by_abort() {
    let store = ResourceStore::new(ResourceStoreConfig::default());
    let data = rgba(2, 1);
    for id in 0..MAX_CONCURRENT_UPLOADS_PER_AGENT as u8 {
        assert!(
            store
                .handle_upload_start(chunked_start("a", id, 2, &data))
                .await
                .unwrap()
                .is_none()
        );
    }

    let err = store
        .handle_upload_start(chunked_start("a", 99, 2, &data))
        .await
        .unwrap_err();
    assert_eq!(err, ResourceError::TooManyUploads);
    // Another agent is unaffected by a's slots.
    store
        .handle_upload_start(chunked_start("b", 99, 2, &data))
        .await
        .unwrap();

    store.abort_upload("a", UploadId::from_bytes([0; 16])).await;
    store
        .handle_upload_start(chunked_start("a", 99, 2, &data))
        .await
        .expect("an aborted upload frees its slot");
}

fn viewer_close_button_dismisses_hovered_tile_and_notifies_owner() {
    use tze_hud_scene::types::{LeaseState, ZoneHitRegion};

    let mut harness = HeadlessEventLoopHarness::new();
    let sender = tze_hud_protocol::session_server::LeaseExpirySender::default();
    let mut notices = sender.subscribe();
    harness.app.state.lease_expirations = Some(sender);
    let (lease_id, tile_id) = {
        let shared = harness.app.state.shared_state.blocking_lock();
        let mut scene = shared.scene.blocking_lock();
        *scene = SceneGraph::new(1920.0, 1080.0);
        let tab = scene.create_tab("Main", 0).unwrap();
        let lease = scene.grant_lease("agent", 60_000);
        let tile = scene
            .create_tile(
                tab,
                "agent",
                lease,
                Rect::new(100.0, 100.0, 400.0, 300.0),
                5,
            )
            .unwrap();
        harness.app.state.pipeline.hit_test_snapshot.store(Arc::new(
            crate::pipeline::HitTestSnapshot::from_scene(&scene),
        ));
        (lease, tile)
    };

    let hover = |app: &mut WinitApp, x: f32, y: f32| {
        app.state.cursor_x = x;
        app.state.cursor_y = y;
        app.push_tile_close_hover();
        *app.state.tile_close_hover_state.lock().unwrap()
    };
    assert_eq!(hover(&mut harness.app, 300.0, 200.0), Some(tile_id));
    assert_eq!(hover(&mut harness.app, 900.0, 900.0), None);
    harness.app.state.cursor_left_window = true;
    assert_eq!(hover(&mut harness.app, 300.0, 200.0), None);
    harness.app.state.cursor_left_window = false;

    // The compositor registers the button's hit region once the tile is
    // hovered; stand in for it here (the harness has no compositor).
    let (bx, by) = (450.0, 110.0);
    harness
        .app
        .state
        .shared_state
        .blocking_lock()
        .scene
        .blocking_lock()
        .overlay
        .zone_hit_regions
        .push(ZoneHitRegion {
            zone_name: "__chrome_tile_close__".into(),
            published_at_wall_us: 0,
            publisher_namespace: "runtime".into(),
            bounds: Rect::new(bx - 10.0, by - 10.0, 20.0, 20.0),
            kind: ZoneInteractionKind::DismissTile { tile_id },
            interaction_id: format!("tile-close:{tile_id}"),
            tab_order: 0,
        });
    harness.click(bx, by);
    harness.drain();

    assert_eq!(harness.tile_count(), 0, "dismiss is local and immediate");
    let notice = tokio::runtime::Builder::new_current_thread()
        .enable_time()
        .build()
        .unwrap()
        .block_on(async {
            tokio::time::timeout(std::time::Duration::from_secs(1), notices.recv()).await
        })
        .expect("the dismissed tile's owner is notified")
        .expect("notice");
    assert_eq!(notice.lease_id, lease_id);
    assert_eq!(notice.terminal_state, LeaseState::Revoked);
    assert_eq!(notice.removed_tiles, vec![tile_id]);
}

fn viewer_dismiss_portal_detaches_and_next_publish_reattaches() {
    let mut driver = InProcessPortalDriver::new();
    let (mut scene, tab, mut processor) = scene();
    publish(&mut driver, "p", "live transcript", 100);
    driver.drain_inner(&mut scene, &mut processor, Some(tab), 100);
    let old_lease = lease(&driver, "p");

    let dismissed = driver.viewer_dismiss_tile(&mut scene, tile(&driver, "p"));
    assert_eq!(
        dismissed.expiry.expect("lease reclaimed").lease_id,
        old_lease
    );
    assert_eq!(scene.tile_count(), 0, "tile removed immediately");
    assert!(!driver.drive.entries.contains_key(&key("p")));
    assert_eq!(
        hold(&mut driver, AGENT, "p", 1_000, 150),
        Err(PortalError::NotHeld)
    );

    publish(&mut driver, "p", "fresh", 200);
    driver.drain_inner(&mut scene, &mut processor, Some(tab), 200);
    assert_eq!(scene.tile_count(), 1, "re-attach paints a fresh portal");
    assert_ne!(lease(&driver, "p"), old_lease);
    let content = tile_markdown(&scene, tile(&driver, "p"));
    assert!(content.contains("fresh") && !content.contains("live transcript"));
}

async fn viewer_dismiss_tile_pushes_reclaimed_override() {
    use std::time::Duration;

    let clock = tze_hud_scene::TestClock::new(1_000);
    let (mut client, server, state, lease_expirations) =
        setup_test_with_lease_expiry_clock(clock).await;
    let (tx, _handshake, mut stream) = handshake(&mut client, "dismiss-agent", "test-key").await;

    tx.send(ClientMessage {
        sequence: 2,
        timestamp_wall_us: now_wall_us(),
        payload: Some(ClientPayload::ClaimTile(ClaimTile {
            ttl_ms: 60_000,
            ..Default::default()
        })),
    })
    .await
    .unwrap();
    let (lease_id, tile_id) = match next_server_msg(&mut stream).await.payload {
        Some(ServerPayload::RequestResult(RequestResult {
            ok: true,
            lease_id,
            ids,
            ..
        })) => (
            bytes_to_scene_id(&lease_id).expect("lease id"),
            bytes_to_scene_id(&ids[0]).expect("tile id"),
        ),
        other => panic!("expected a granted ClaimTile, got {other:?}"),
    };

    let expiry = {
        let shared = state.lock().await;
        let mut scene = shared.scene.lock().await;
        let expiry = scene
            .viewer_dismiss_tile(tile_id)
            .expect("viewer dismiss reclaims the lease");
        assert_eq!(expiry.terminal_state, LeaseState::Revoked);
        assert_eq!(scene.tile_count(), 0, "the tile is gone immediately");
        expiry
    };
    assert_eq!(lease_expirations.publish(expiry.into()), 1);

    let reclaimed = tokio::time::timeout(Duration::from_secs(1), stream.next())
        .await
        .expect("Reclaimed must arrive promptly")
        .expect("stream stays open")
        .expect("valid message");
    match reclaimed.payload {
        Some(ServerPayload::Reclaimed(Reclaimed {
            surface,
            why,
            lease_id: reclaimed_lease,
        })) => {
            assert_eq!(why, ReclaimReason::Override as i32);
            assert_eq!(reclaimed_lease, scene_id_to_bytes(lease_id));
            assert_eq!(surface, crate::session_server::verbs::tile_surface(tile_id));
        }
        other => panic!("expected Reclaimed, got {other:?}"),
    }

    drop(tx);
    server.abort();
}

fn viewer_dismiss_tile_revokes_lease_in_any_live_state() {
    let mut scene = SceneGraph::new(1920.0, 1080.0);
    scene.zone_registry = ZoneRegistry::with_defaults();
    let tab = scene.create_tab("Main", 0).unwrap();
    let tile_for = |scene: &mut SceneGraph, ns: &str, lease| {
        scene
            .create_tile(tab, ns, lease, Rect::new(0.0, 0.0, 100.0, 100.0), 1)
            .unwrap()
    };

    let bystander_lease = scene.grant_lease("other", 60_000);
    let bystander_tile = tile_for(&mut scene, "other", bystander_lease);
    scene
        .publish_to_zone_for_lease(
            "pip",
            ZoneContent::SolidColor(Rgba::WHITE),
            "other",
            None,
            None,
            None,
            Vec::new(),
            Some(bystander_lease),
        )
        .unwrap();

    for previous in [
        LeaseState::Active,
        LeaseState::Orphaned,
        LeaseState::Suspended,
    ] {
        let lease = scene.grant_lease("agent", 60_000);
        let (tile, second) = (
            tile_for(&mut scene, "agent", lease),
            tile_for(&mut scene, "agent", lease),
        );
        scene
            .publish_to_zone_for_lease(
                "subtitle",
                ZoneContent::StreamText("agent".into()),
                "agent",
                None,
                None,
                None,
                Vec::new(),
                Some(lease),
            )
            .unwrap();
        match previous {
            LeaseState::Orphaned => scene.disconnect_lease(&lease, 1_000).unwrap(),
            LeaseState::Suspended => scene.suspend_lease(&lease, 1_000).unwrap(),
            _ => {}
        }

        let expiry = scene.viewer_dismiss_tile(tile).expect("lease reclaimed");
        assert_eq!(expiry.lease_id, lease);
        assert_eq!(expiry.previous_state, previous);
        assert_eq!(expiry.terminal_state, LeaseState::Revoked);
        let mut removed = expiry.removed_tiles.clone();
        removed.sort();
        let mut both = vec![tile, second];
        both.sort();
        assert_eq!(removed, both, "dismiss reclaims the lease's other tile too");
        assert!(!scene.tiles.contains_key(&tile) && !scene.tiles.contains_key(&second));
        assert!(
            scene
                .zone_registry
                .active_for_zone("subtitle")
                .iter()
                .all(|r| r.publisher_namespace != "agent"),
            "the lease's zone publication is reclaimed"
        );
        assert!(
            scene.viewer_dismiss_tile(tile).is_none(),
            "a second dismiss finds nothing to reclaim"
        );
        assert!(scene.tiles.contains_key(&bystander_tile));
        assert!(
            scene
                .zone_registry
                .active_for_zone("pip")
                .iter()
                .any(|r| r.publisher_namespace == "other"),
            "another agent's publication survives"
        );
    }
}

fn widget_publish_with_suspended_lease_is_safe_mode_active() {
    let (mut scene, _tab) = scene_with_gauge(ContentionPolicy::LatestWins);
    let lease = scene.grant_lease("agent.test", 300_000);
    let params =
        || std::collections::HashMap::from([("level".to_string(), WidgetParameterValue::F32(0.5))]);
    scene.suspend_lease(&lease, 1).unwrap();
    let result = scene.publish_to_widget("gauge", params(), "agent.test", None, 0, None);
